import { useEffect, useState } from 'react'
import { db } from '@/data/db'
import type { FailureClass, Incident, InterventionClass, Policy } from '@/data/types'
import type { PlanDraft } from '@/lib/plan'

// ---- Phase 1 data (p1_planner.json, generated by generate.py §15b) --------------------------
export interface P1Feature {
  id: string
  label: string
  unit: string
  source: string
  window: string
  definition: string
  direction: 1 | -1
  importance: number
  pop_p50: number
  pop_p90: number
}
export interface P1Site {
  site_id: string
  failure_class: FailureClass
  p8: number
  values: Record<string, number>
  contrib: Record<string, number> // probability points; sum + base rate = p8
  runs: number[] // p(W+8) on the last 9 weekly runs, oldest first, last = today
  first_flagged_run: number | null
  ci90: [number, number]
}
export interface P1Model {
  failure_class: FailureClass
  wave: number
  horizon: string
  precision_top_decile: number
  recall: number
  false_positive_rate: number
  override_rate: number
  drift_psi: number
  status: string
  backtest_months: number
  base_rate: number
  algorithm: string
  label: string
  training_window: string
  features: number
  versions: { version: string; date: string; note: string }[]
  current_version: string
  pr_curve: { recall: number; precision: number }[]
  calibration: { bin: string; predicted: number; observed: number; n: number }[]
  lift_by_decile: number[]
  precision_monthly: { month: string; precision: number }[]
  confusion_at_threshold: { threshold: number; tp: number; fp: number; fn: number; tn: number; population?: string }
  precision_metric?: string
  alert_share?: number
  retrain: string
  owner: string
}
export interface P1Data {
  as_of: string
  freshness: string
  run_dates: string[]
  feature_catalog: Record<FailureClass, P1Feature[]>
  base_rate: Record<FailureClass, number>
  sites: P1Site[]
  models: P1Model[]
  bySite: Map<string, P1Site>
}

let cache: P1Data | null = null
let pending: Promise<P1Data> | null = null

export function loadP1(): Promise<P1Data> {
  if (cache) return Promise.resolve(cache)
  if (!pending)
    pending = fetch('/data/p1_planner.json')
      .then((r) => r.json())
      .then((d: Omit<P1Data, 'bySite'>) => {
        cache = { ...d, bySite: new Map(d.sites.map((s) => [s.site_id, s])) }
        return cache
      })
  return pending
}

/** Phase 1 data hook. Returns null until loaded (pages show a skeleton). */
export function useP1(): P1Data | null {
  const [d, setD] = useState<P1Data | null>(cache)
  useEffect(() => {
    if (!d) loadP1().then(setD)
  }, [d])
  return d
}

