// ---- Forecast clusters ---------------------------------------------------------------------
// Forecast Orchestrator output: one cluster per root cause. In this prototype the clusters
// are the predicted incidents from the base data, relabelled CL-.
export interface Cluster {
  id: string
  incident_id: string
  title: string
  cls: FailureClass
  site_ids: string[]
  province_id: string
  district_id: string
  region: string
  probability: number
  crossing_week: number
  exposure_idr: number
  priority: number
  coverage: Incident['program_match']
  recommended_rank: number
  story?: string
  days_to_breach?: number
}

export function clusterId(incidentId: string): string {
  return incidentId.replace('INC-', 'CL-')
}

export function clustersFrom(incidents: Incident[]): Cluster[] {
  return incidents
    .filter((x) => x.source === 'prediction' && (CLASSES as string[]).includes(x.class) && !['Closed', 'Rejected', 'Validating'].includes(x.status))
    .map((x) => ({
      id: clusterId(x.incident_id),
      incident_id: x.incident_id,
      title: x.title.replace(/^.*? — /, ''),
      cls: x.class as FailureClass,
      site_ids: x.site_ids,
      province_id: x.province_id,
      district_id: x.district_id,
      region: x.region,
      probability: x.probability,
      crossing_week: x.predicted_week,
      exposure_idr: x.exposure_idr,
      priority: x.priority_score,
      coverage: x.program_match,
      recommended_rank: x.recommended_rank,
      story: x.story,
      days_to_breach: x.days_to_breach,
    }))
    .sort((a, b) => b.priority - a.priority)
}

export function optionsFor(c: Cluster) {
  return db().optionsByIncident.get(c.incident_id) ?? []
}

// ---- Approval routing for a plan (DoA) -------------------------------------------------------
export interface PlanRoute {
  role: 'PLAN' | 'EXEC' | 'REGION' | 'OPS' | 'PROC'
  label: string
  cosign: string | null
  auto: boolean
  note: string
}

export function planRoute(cls: InterventionClass, totalIdr: number, p: Policy): PlanRoute {
  switch (cls) {
    case 'noncapex_zero':
      return { role: 'OPS', label: 'NOC shift lead', cosign: null, auto: true, note: 'Zero cost: auto-approved with post-hoc review' }
    case 'noncapex_opex':
      return totalIdr < p.opex_auto_approve_below_idr
        ? { role: 'REGION', label: 'Regional Network Manager', cosign: null, auto: true, note: `OpEx below ${Math.round(p.opex_auto_approve_below_idr / 1e6)}m: auto-approved` }
        : { role: 'REGION', label: 'Regional Network Manager', cosign: null, auto: false, note: 'Non-CapEx OpEx' }
    case 'capex_minor':
      return totalIdr <= p.decision_threshold_idr
        ? { role: 'REGION', label: 'Regional Network Manager', cosign: null, auto: false, note: `Minor CapEx at or below IDR ${Math.round(p.decision_threshold_idr / 1e6)}m` }
        : { role: 'PLAN', label: 'Head of Planning', cosign: null, auto: false, note: 'Minor CapEx above the Stage 3 threshold' }
    case 'capex_major':
      return { role: 'EXEC', label: 'Head of Network', cosign: totalIdr > p.cfo_cosign_above_idr ? 'CFO' : null, auto: false, note: 'Major CapEx' }
    default:
      return { role: 'PLAN', label: 'Head of Planning', cosign: null, auto: false, note: '' }
  }
}

// ---- Plans ------------------------------------------------------------------------------
export type PlanStatus = 'draft' | 'pending_approval' | 'approved' | 'handed_off' | 'rejected' | 'deferred'
export type HandoffState = 'not_sent' | 'sent' | 'acknowledged' | 'failed'

export interface P1Plan {
  id: string
  name: string
  status: PlanStatus
  cluster_id: string | null
  draft: PlanDraft
  created: string
  created_by: string
  submitted?: string
  decided?: string
  decided_by?: string
  reason?: string | null
  route: PlanRoute
  history: { ts: string; who: string; role: string; what: string; reason?: string | null }[]
  handoffs: Record<string, { state: HandoffState; ref?: string; ts?: string }>
}

export const HANDOFF_TARGETS = ['HO-ERP', 'HO-BOQ', 'HO-VENDOR', 'HO-TOWERCO', 'HO-WMS'] as const

export const PHASE1_ROLES = ['PLAN', 'PROC', 'EXEC', 'DEPLOY', 'OPS', 'REGION'] as const
